description:
Design a 4-bit binary counter with a finite state machine (FSM) that counts from 0 to 15 sequentially. The counter increments its count upon every clock cycle while in states S0 to S14, transitioning to the next state until it reaches S15, where it loops back to S0. The module includes a reset input to initialize the counter and FSM to zero, and an output signal, "match," which asserts high only when the counter value (state) is equal to 10 (S10). This functionality makes the design suitable for applications requiring precise counting and monitoring of a specific count state.
module top_module(
  input clk,
  input reset,
  output reg match
);

code:
module top_module(
  input clk,
  input reset,
  output reg match
);reg [3:0] count;
reg [3:0] next_count;
reg [3:0] state;
reg [3:0] next_state;

parameter S0 = 4'b0000;
parameter S1 = 4'b0001;
parameter S2 = 4'b0010;
parameter S3 = 4'b0011;
parameter S4 = 4'b0100;
parameter S5 = 4'b0101;
parameter S6 = 4'b0110;
parameter S7 = 4'b0111;
parameter S8 = 4'b1000;
parameter S9 = 4'b1001;
parameter S10 = 4'b1010;
parameter S11 = 4'b1011;
parameter S12 = 4'b1100;
parameter S13 = 4'b1101;
parameter S14 = 4'b1110;
parameter S15 = 4'b1111;

always @ (posedge clk or posedge reset) begin
  if (reset) begin
    count <= 4'b0000;
    state <= S0;
    match <= 1'b0;
  end else begin
    count <= next_count;
    state <= next_state;
    match <= (state == S10);
  end
end

always @ (*) begin
  case (state)
    S0: begin
      next_state = S1;
      next_count = 4'b0001;
    end
    S1: begin
      next_state = S2;
      next_count = 4'b0010;
    end
    S2: begin
      next_state = S3;
      next_count = 4'b0011;
    end
    S3: begin
      next_state = S4;
      next_count = 4'b0100;
    end
    S4: begin
      next_state = S5;
      next_count = 4'b0101;
    end
    S5: begin
      next_state = S6;
      next_count = 4'b0110;
    end
    S6: begin
      next_state = S7;
      next_count = 4'b0111;
    end
    S7: begin
      next_state = S8;
      next_count = 4'b1000;
    end
    S8: begin
      next_state = S9;
      next_count = 4'b1001;
    end
    S9: begin
      next_state = S10;
      next_count = 4'b1010;
    end
    S10: begin
      next_state = S10;
      next_count = 4'b1010;
    end
    S11: begin
      next_state = S12;
      next_count = 4'b1100;
    end
    S12: begin
      next_state = S13;
      next_count = 4'b1101;
    end
    S13: begin
      next_state = S14;
      next_count = 4'b1110;
    end
    S14: begin
      next_state = S15;
      next_count = 4'b1111;
    end
    S15: begin
      next_state = S0;
      next_count = 4'b0000;
    end
  endcase
end

endmodule

