module fsm_operation (
        input clk,
        input rst,
        input start,
        input finish,
        output reg out);

    parameter INIT = 0, OPERATE = 1, COMPLETE = 2;
    reg [1:0] state, next_state;

    always @(posedge clk) begin
        if (rst) state <= INIT;
        else state <= next_state;
    end

    always_comb begin
        case (state)
            INIT: next_state = start ? OPERATE : INIT;
            OPERATE: next_state = finish ? COMPLETE : OPERATE;
            COMPLETE: next_state = rst ? INIT : COMPLETE;
            default: next_state = 'x;
        endcase
    end

    assign out = (state == OPERATE) || (state == COMPLETE);

endmodule

