module top_module(
  input clk,
  input rst_n,
  input push,
  input pop,
  input [7:0] datain,
  output empty,
  output almost_empty,
  output full,
  output almost_full,
  output reg error,  // Changed to reg type
  output reg [7:0] dataout
);parameter WIDTH = 8;
  parameter DEPTH = 256;
  parameter ADDR_WIDTH = $clog2(DEPTH);

  reg [WIDTH-1:0] mem [0:DEPTH-1];
  reg [ADDR_WIDTH-1:0] head;
  reg [ADDR_WIDTH-1:0] tail;
  reg [ADDR_WIDTH-1:0] count;

  assign empty = (count == 0);
  assign almost_empty = (count <= 4);
  assign full = (count == DEPTH);
  assign almost_full = (count >= DEPTH - 4);

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      head <= 0;
      tail <= 0;
      count <= 0;
      dataout <= 0;
      error <= 0;  // Initialize error at reset
    end else begin
      error <= 0;  // Reset error at the start of the clock cycle
      if (push && !pop && !full) begin
        mem[head] <= datain;
        head <= head + 1;
        count <= count + 1;
      end else if (!push && pop && !empty) begin
        dataout <= mem[tail];
        tail <= tail + 1;
        count <= count - 1;
      end else if (push && pop) begin
        error <= 1;  // Set error if both push and pop are active
      end
    end
  end

endmodule

