module sequence_detector (
	input clk,
	input resetn,
	input serial_in,
	output match);

	parameter IDLE=0, S1=1, S11=2, S110=3, S1101=4;
	reg [2:0] state, next_state;

	always @(posedge clk) begin
		if (~resetn) state <= IDLE;
		else state <= next_state;
	end

	always_comb begin
		case (state)
			IDLE: next_state = serial_in ? S1 : IDLE;
			S1: next_state = serial_in ? S11 : IDLE;
			S11: next_state = serial_in ? S11 : S110;
			S110: next_state = serial_in ? S1101 : IDLE;
			S1101: next_state = serial_in ? S1 : IDLE;
			default: next_state = IDLE;
		endcase
	end

	assign match = (state == S1101);
endmodule

