        wr_bank <= 2'd0;
    else if(~vin_vs_d1 & vin_vs_d0) 
        wr_bank <= wr_bank + 2'd1;
end

always@(posedge clk or negedge rst_n)
begin
    if(~rst_n)
        rd_bank <= 2'd0;
    else if(~vout_vs_d1 & vout_vs_d0) 
        rd_bank <= wr_bank - 2'd1;
end
endmodule

