module top_module(
    data,
    wrreq,
    rdreq,
    clock,
    aclr,
    q,
    full,
    empty,
    usedw
);input  [31:0]  data;
input          wrreq;
input          rdreq;
input          clock;
input          aclr;
output [31:0]  q;
output         full;
output         empty;
output [6:0]   usedw;

reg [31:0] buffer[0:31];
reg [5:0]  head = 0;
reg [5:0]  tail = 0;
reg [6:0]  usedw_reg = 0;
wire full_reg = (usedw_reg == 32);
wire empty_reg = (usedw_reg == 0);

// Change q from wire to reg to allow assignment within the always block
reg [31:0] q_reg;

always @(posedge clock) begin
    if (aclr) begin
        head <= 0;
        tail <= 0;
        usedw_reg <= 0;
        q_reg <= 32'b0; // Reset q_reg on aclr
    end else begin
        if (wrreq && !full_reg) begin
            buffer[head] <= data;
            head <= (head + 1) % 32;
            usedw_reg <= usedw_reg + 1;
        end
        if (rdreq && !empty_reg) begin
            q_reg <= buffer[tail]; // Assign to q_reg instead of q
            tail <= (tail + 1) % 32;
            usedw_reg <= usedw_reg - 1;
        end
    end
end

// Assign q_reg to q
assign q = q_reg;
assign full = full_reg;
assign empty = empty_reg;
assign usedw = usedw_reg;

endmodule

