	if (!resetn) begin
		prev_state <= 4'd0;
		key_pressed <= 4'd0;
		key_held <= 4'd0;
		key_released <= 4'd0;
	end
	else begin
		key_pressed <= ~KEY & (~prev_state);
		key_held <= ~KEY;
		key_released <= KEY & prev_state;
		prev_state <= ~KEY;
	end
end

endmodule

