module top_module(
  input [3:0] A,
  input [3:0] B,
  input Cin,
  output reg [4:0] C
);always @(A, B, Cin) begin
    // Perform the binary addition operation
    C[0] = A[0] ^ B[0] ^ Cin;
    C[1] = A[1] ^ B[1] ^ ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin));
    C[2] = A[2] ^ B[2] ^ ((A[1] & B[1]) | (A[1] & C[1]) | (B[1] & C[1]));
    C[3] = A[3] ^ B[3] ^ ((A[2] & B[2]) | (A[2] & C[2]) | (B[2] & C[2]));
    C[4] = (A[3] & B[3]) | (A[3] & C[3]) | (B[3] & C[3]);
  end

endmodule

