module fsm (
	input clk,
	input reset,
	input g,
	input h,
	output reg o);

	parameter M=0, N=1, S1=2, S2=3, S3=4, S4=5, S5=6;
	reg [2:0] state, next;

	always @(posedge clk) begin
		if (reset) state <= M;
		else state <= next;
	end

	always_comb begin
		case (state)
			M: next = g ? N : M;
			N: next = h ? S1 : S2;
			S1: next = h ? S2 : S3;
			S2: next = h ? S3 : S4;
			S3: next = h ? S4 : S5;
			S4: next = h ? S5 : M;
			S5: next = g ? N : M;
			default: next = 'x;
		endcase
	end

	assign o = (state == S1);

endmodule

