module fsm (
        input clk,
        input reset,
        input k,
        output reg y);parameter H0=0, H1=1, H2=2;
	reg [1:0] state, next;

	always @(posedge clk)
		if (reset)
			state <= H0;
		else 
			state <= next;


	always_comb begin
		case(state)
			H0: next = k ? H2 : H1;
			H1: next = k ? H0 : H2;
			H2: next = k ? H0 : H1;
			default: next = 'x;
		endcase
	end

	assign y = (state == H1);

endmodule

