description:
Design a programmable Johnson counter with 'n' output bits. The counter's state updates on the rising edge of the clock signal, utilizing a distinctive feedback mechanism that generates a sequence by performing exclusive OR (XOR) operations between specific bits of the current state. The output reflects the current state of the counter, producing a cyclical sequence of binary values that represent the state of the counter as it progresses through its defined states.
module top_module(
  input clk,
  output [n-1:0] out
);

code:
module top_module(
  input clk,
  output [n-1:0] out
);parameter n = 4; // number of output signals

  reg [n-1:0] state;
  wire [n-1:0] next_state;

  assign out = state;

  always @ (posedge clk) begin
    state <= next_state;
  end

  assign next_state[0] = state[n-1] ^ state[0];
  assign next_state[1] = state[0] ^ state[1];
  assign next_state[2] = state[1] ^ state[2];
  assign next_state[3] = state[2] ^ state[3];

endmodule

