module top_module(
    input signed [3:0] a,
    input signed [3:0] b,
    output signed [7:0] result,
    output overflow
);reg signed [7:0] product;
reg [2:0] state;

assign overflow = (product > 7 || product < -8);

always @(*) begin
    case(state)
        3'b000: begin
            product <= {4'b0, a};
            state <= 3'b001;
        end
        3'b001: begin
            if(b[0] == 1) begin
                product <= product - a;
            end
            state <= 3'b010;
        end
        3'b010: begin
            product <= product >> 1;
            state <= 3'b011;
        end
        3'b011: begin
            product <= {product[6:0], product[7]};
            state <= 3'b100;
        end
        3'b100: begin
            if(b[1] == 1) begin
                product <= product - a;
            end
            state <= 3'b101;
        end
        3'b101: begin
            product <= product >> 1;
            state <= 3'b110;
        end
        3'b110: begin
            product <= {product[6:0], product[7]};
            state <= 3'b111;
        end
        3'b111: begin
            if(b[2] == 1) begin
                product <= product - a;
            end
            state <= 3'b000;
        end
    endcase
end

assign result = product;

endmodule

