module top_module(
  input clk,
  input rst,
  input xtal,
  output reg clk_div,
  output reg pd_out
);parameter f_clk = 50000000; // input clock frequency
parameter f_xtal = 25000000; // crystal oscillator frequency
parameter n = 8; // number of bits in divider chain

reg [n-1:0] divider; // divider chain
reg ref_clk; // reference clock signal

always @(posedge clk or posedge rst) begin
  if (rst) begin
    divider <= 0;
    ref_clk <= 0;
    clk_div <= 0;
    pd_out <= 0;
  end else begin
    // increment divider chain
    if (divider == (1 << n) - 1) begin
      divider <= 0;
    end else begin
      divider <= divider + 1;
    end

    // generate reference clock signal
    if (divider == 0) begin
      ref_clk <= ~ref_clk;
    end

    // generate divided clock signal
    if (divider == (1 << (n-1)) - 1) begin
      clk_div <= ~clk_div;
    end

    // generate phase detector output signal
    if (ref_clk == xtal) begin
      pd_out <= 0;
    end else if (ref_clk == ~xtal) begin
      pd_out <= 1;
    end
  end
end

endmodule

