description:
Design a reset synchronizer that generates a synchronized reset signal from an asynchronous reset input. The output `sync_reset` is held low for a specified number of clock cycles (defined by the `delay` parameter) after the `async_reset` goes high. The design utilizes a shift register to capture the state of `async_reset` over multiple clock cycles, ensuring that `sync_reset` only transitions to high when the asynchronous reset is not asserted for the duration of the delay, thereby preventing possible metastability issues in synchronous systems.
module top_module(
  input async_reset,
  input clk,
  output sync_reset
);

code:
module top_module(
  input async_reset,
  input clk,
  output sync_reset
);parameter delay = 3; // number of clock cycles for which sync_reset should be low

reg sync_reset_reg;
reg [delay-1:0] delay_chain;

always @(posedge clk) begin
  delay_chain <= {delay_chain[(delay-2):0], async_reset}; // shift in async_reset signal
  sync_reset_reg <= ~(|delay_chain); // sync_reset is low when any bit in delay_chain is high
end

assign sync_reset = sync_reset_reg;

endmodule

