module top_module(
    input wire clk,
    input wire clr,
    output reg hsync,
    output reg vsync,
    output reg [11:0] hc,
    output reg [11:0] vc,
    output wire vidon
);/* 1024x768@60MHz */
parameter hpixels = 12'd1344;
parameter vlines  = 12'd806;
parameter hsp   = 12'd136;
parameter hbp   = 12'd160;
parameter hfp   = 12'd24;
parameter vsp   = 12'd6;
parameter vbp   = 12'd29;
parameter vfp   = 12'd3;
/* */

reg vsenable;

initial begin
    hc <= hpixels - hsp - hbp;
    vc <= vlines - vsp - vbp;
    hsync <= 0;
    vsync <= 0;
    vsenable <= 0;
end

always @(posedge clk or posedge clr) begin
    if(clr == 1) begin
        hc <= hpixels - hsp - hbp;
    end else begin
        if(hc == hpixels - 1) begin
            hc <= 0;
            vsenable <= 1;
        end else begin
            hc <= hc + 1'b1;
            vsenable <= 0;
        end
    end
end

always @(*) begin
    if(hpixels - hsp - hbp < hc && hc <= hpixels - hbp) begin
        hsync = 0;
    end else begin
        hsync = 1;
    end
end

always @(posedge clk or posedge clr) begin
    if(clr == 1) begin
        vc <= vlines - vsp - vbp;
    end else if(vsenable == 1) begin
        if(vc == vlines - 1) begin
            vc <= 0;
        end else begin
            vc <= vc + 1'b1;
        end
    end
end

always @(*) begin
    if(vlines - vsp - vbp < vc && vc <= vlines - vbp) begin
        vsync = 0;
    end else begin
        vsync = 1;
    end
end

assign vidon=(hc<hpixels-hfp-hsp-hbp)&&(vc<vlines-vfp-vsp-vbp);

endmodule

module top_module(
    input [3:0] data1,
    input [3:0] data2,
    input [1:0] op,
    input clk,         // Added clk input
    output reg [3:0] q
);reg [3:0] stage1_out;
reg [3:0] stage2_out;

always @(*) begin
    case(op)
        2'b00: stage1_out = data1 + data2;
        2'b01: stage1_out = data1 - data2;
        2'b10: stage1_out = data1 & data2;
        2'b11: stage1_out = data1 | data2;
        default: stage1_out = 4'b0000; // Added default case
    endcase
end

always @(posedge clk) begin
    stage2_out <= stage1_out;
    q <= stage2_out;
end

endmodule

